UPDATE `odometer_entries` SET `source_trip_id` = COALESCE((SELECT `trips`.`id` FROM `trips` WHERE `trips`.`vehicle_id` = `odometer_entries`.`vehicle_id` AND `trips`.`user_id` = `odometer_entries`.`user_id` AND `trips`.`end_odometer` = `odometer_entries`.`odometer` AND `trips`.`trip_date` = `odometer_entries`.`recorded_at` ORDER BY `trips`.`created_at`, `trips`.`id` LIMIT 1), (SELECT `trips`.`id` FROM `trips` WHERE `trips`.`vehicle_id` = `odometer_entries`.`vehicle_id` AND `trips`.`user_id` = `odometer_entries`.`user_id` AND `trips`.`end_odometer` = `odometer_entries`.`odometer` AND date(`trips`.`trip_date`, 'unixepoch') = date(`odometer_entries`.`recorded_at`, 'unixepoch') ORDER BY `trips`.`created_at`, `trips`.`id` LIMIT 1)) WHERE `source_trip_id` IS NULL AND `note` = 'From trip';
